style.css:
@-moz-document domain("youtube.com") {
/* Wallpaper background */
  html, body {
    background: url("https://i.pinimg.com/1200x/36/09/7d/36097d10c54d49a96a355ce098c7180a.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Make main containers transparent so wallpaper shows */
  #content, #page-manager, #masthead-container, #guide-content {
    background: transparent !important;
  }

  /* Change link colors */
  a {
    color: gainsboro !important;
  }

  /* Example: tweak footer text */
  #footer-links {
    color: gainsboro !important;
    border-top: 1px solid #cccbcb5e !important;
  }

  /* Replace YouTube logo with One Piece logo */
  #logo-icon {
    background: url("https://1000logos.net/wp-content/uploads/2022/08/One-Piece-Logo.png") no-repeat center center !important;
    background-size: contain !important;
  }
}
